def max_value_on_paths(N: int, grid_values: list) -> int:
    """Calculate the maximum sum of values collected on two non-overlapping paths
    in an N x N grid. Each cell value may be collected at most once."""
    # Build the grid
    grid = [[0] * N for _ in range(N)]
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x - 1][y - 1] = v
    # DP initialization: dp[i1][i2] is max sum when first path at row i1, second at row i2
    NEG_INF = -10**18
    dp = [[NEG_INF] * N for _ in range(N)]
    dp[0][0] = grid[0][0]
    # Total steps from (0,0) to (N-1,N-1) is 2*(N-1)
    for step in range(0, 2 * (N - 1)):
        newdp = [[NEG_INF] * N for _ in range(N)]
        i_min = max(0, step - (N - 1))
        i_max = min(N - 1, step)
        for i1 in range(i_min, i_max + 1):
            j1 = step - i1
            if j1 < 0 or j1 >= N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = step - i2
                if j2 < 0 or j2 >= N:
                    continue
                cur = dp[i1][i2]
                if cur == NEG_INF:
                    continue
                # Move options: down (1,0) or right (0,1)
                for di1, dj1 in (1, 0), (0, 1):
                    ni1 = i1 + di1
                    nj1 = j1 + dj1
                    if ni1 >= N or nj1 >= N:
                        continue
                    for di2, dj2 in (1, 0), (0, 1):
                        ni2 = i2 + di2
                        nj2 = j2 + dj2
                        if ni2 >= N or nj2 >= N:
                            continue
                        add = grid[ni1][nj1]
                        if not (ni1 == ni2 and nj1 == nj2):
                            add += grid[ni2][nj2]
                        total = cur + add
                        if total > newdp[ni1][ni2]:
                            newdp[ni1][ni2] = total
        dp = newdp
    return dp[N - 1][N - 1] if dp[N - 1][N - 1] != NEG_INF else 0

