def count_coprime_pairs(x0: int, y0: int) -> int:
    """Counts the number of ordered pairs of positive integers (P, Q) such that
    gcd(P, Q) == x0 and lcm(P, Q) == y0.
    The count includes both (P, Q) and (Q, P) as distinct pairs unless P == Q.
    """
    # Validate inputs
    if not isinstance(x0, int) or not isinstance(y0, int):
        return 0
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0:
        return 0

    k = y0 // x0  # scaled down product for coprime factors

    def gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    i = 1
    while i * i <= k:
        if k % i == 0:
            a = i
            b = k // i
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2  # (a,b) and (b,a)
        i += 1

    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    """
    Reconstructs a binary tree from its inorder and postorder traversals
    and returns the preorder traversal as a string. The function assumes
    all node labels are unique characters.

    Raises:
        ValueError: If input strings are of different lengths, contain
                    duplicate characters, or do not represent the same set
                    of nodes.
    """
    if not inorder and not postorder:
        return ""

    if len(inorder) != len(postorder):
        raise ValueError("Inorder and postorder strings must be of the same length.")

    # Ensure all characters are unique and both strings contain the same set
    if len(set(inorder)) != len(inorder) or len(set(postorder)) != len(postorder):
        raise ValueError("All nodes must have unique labels.")
    if set(inorder) != set(postorder):
        raise ValueError("Inorder and postorder strings must contain the same nodes.")

    # Map from node label to its index in the inorder string for O(1) lookup
    index_map = {char: idx for idx, char in enumerate(inorder)}

    def helper(in_start: int, in_end: int, post_start: int, post_end: int) -> str:
        if in_start > in_end:
            return ""

        root = postorder[post_end]
        root_idx = index_map.get(root)
        if root_idx is None:
            raise ValueError(f"Node '{root}' not found in inorder traversal.")

        left_count = root_idx - in_start
        right_count = in_end - root_idx

        left_pre = helper(
            in_start, root_idx - 1,
            post_start, post_start + left_count - 1
        )
        right_pre = helper(
            root_idx + 1, in_end,
            post_start + left_count, post_end - 1
        )
        return root + left_pre + right_pre

    return helper(0, len(inorder) - 1, 0, len(postorder) - 1)

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder and not postorder:
        return ''
    if len(inorder) != len(postorder):
        return ''
    try:
        index_map = {char: i for i, char in enumerate(inorder)}
    except Exception:
        return ''
    n = len(inorder)

    def build(in_left: int, in_right: int, post_left: int, post_right: int) -> str:
        if in_left > in_right or post_left > post_right:
            return ''
        root = postorder[post_right]
        in_index = index_map.get(root)
        if in_index is None or in_index < in_left or in_index > in_right:
            return ''
        left_size = in_index - in_left
        right_size = in_right - in_index
        # Validate that substring sizes match
        if left_size < 0 or right_size < 0:
            return ''
        left_pre = build(in_left, in_index - 1, post_left, post_left + left_size - 1)
        right_pre = build(in_index + 1, in_right, post_left + left_size, post_right - 1)
        return root + left_pre + right_pre

    return build(0, n - 1, 0, n - 1)

def preorder_traversal(inorder: str, postorder: str) -> str:
