    def build(i_start, i_end, p_start, p_end):
        if i_start > i_end or p_start > p_end:
            return ''
        root = postorder[p_end]
        root_idx = index_map[root]
        left_size = root_idx - i_start
        left_pre = build(i_start, root_idx - 1, p_start, p_start + left_size - 1)
        right_pre = build(root_idx + 1, i_end, p_start + left_size, p_end - 1)
        return root + left_pre + right_pre
    return build(0, n - 1, 0, n - 1)

