def is_prime(num: int) -> bool:
    """
    Determine whether an integer is a prime number using the 6k ± 1 optimization.

    Parameters:
        num (int): The integer to check for primality.

    Returns:
        bool: True if `num` is a prime number, False otherwise.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False

    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying
    transformation rules recursively using breadth‑first search.

    Args:
        n (int): The original integer.
        rules (list of tuples): Each tuple (x, y) means digit x can be
                                transformed into digit y.

    Returns:
        int: Count of unique numbers reachable from n, including n itself.
    """
    # Build a mapping from source digit to list of possible target digits
    rule_map = {}
    for src, dst in rules:
        try:
            src_digit = int(src)
            dst_digit = int(dst)
        except ValueError:
            continue  # skip invalid rules
        rule_map.setdefault(src_digit, []).append(dst_digit)

    # BFS initialization
    visited = {n}
    queue = [n]
    ptr = 0

    while ptr < len(queue):
        current = queue[ptr]
        ptr += 1
        s = str(current)

        # For each position in the number, try applicable rules
        for idx, ch in enumerate(s):
            digit = int(ch)
            if digit not in rule_map:
                continue
            for replacement in rule_map[digit]:
                # Avoid transforming digit to itself – would create duplicate
                if replacement == digit:
                    continue
                new_s = s[:idx] + str(replacement) + s[idx + 1 :]
                new_num = int(new_s)
                if new_num not in visited:
                    visited.add(new_num)
                    queue.append(new_num)

    return len(visited)

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers by applying transformation rules to the digits of n.

    Args:
        n (int): The original non-negative integer.
        rules (list of tuples): Each tuple is (x, y) meaning digit x can be transformed to y.

    Returns:
        int: Count of unique numbers that can be generated, including the original.
    """
    # Input validation
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    if not isinstance(rules, list):
        raise ValueError("rules must be a list of (x, y) tuples")

    # Build mapping from digit to list of possible replacements
    mapping = {}
    for rule in rules:
        if (
            not isinstance(rule, tuple)
            or len(rule) != 2
            or not isinstance(rule[0], int)
            or not isinstance(rule[1], int)
            or rule[0] < 0
            or rule[0] > 9
            or rule[1] < 0
            or rule[1] > 9
        ):
            raise ValueError("Each rule must be a tuple of two digits (0-9)")
        key = str(rule[0])
        mapping.setdefault(key, []).append(str(rule[1]))

    start = str(n)
    from collections import deque

    visited = {start}
    queue = deque([start])

    while queue:
        cur = queue.popleft()
        for idx, digit in enumerate(cur):
            if digit in mapping:
                for replacement in mapping[digit]:
                    new_num = cur[:idx] + replacement + cur[idx + 1 :]
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

