def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    import re

    # Helper to detect if statement references a day of the week
    def statement_refers_day(s: str) -> bool:
        words = re.findall(r"[A-Za-z]+", s.lower())
        return any(word.upper() in days_of_week for word in words)

    # Determine guilt status for each participant
    guilty = {name: (name == scenario) for name in statements}

    # Helper to evaluate truth of a single statement
    def evaluate(statement: str, speaker: str) -> bool | None:
        s = statement.lower().strip()
        # Self statements
        if s in ("i am guilty.", "i am guilty"):
            return guilty[speaker]
        if s in ("i am not guilty.", "i am not guilty"):
            return not guilty[speaker]
        # Statements about others
        for name in guilty:
            name_low = name.lower()
            if s.startswith(name_low + " is guilty"):
                return guilty[name]
            if s.startswith(name_low + " is not guilty"):
                return not guilty[name]
        # If statement cannot be parsed, return None
        return None

    for speaker, stmts in statements.items():
        for stmt in stmts:
            if statement_refers_day(stmt):
                continue  # ignore day-of-week statements
            truth_value = evaluate(stmt, speaker)
            # If we cannot interpret the statement, we treat it as neutral
            if truth_value is None:
                continue
            is_lier = speaker in liar_count
            # Liars always lie, truth-tellers always tell the truth
            if is_lier and truth_value:
                return False
            if not is_lier and not truth_value:
                return False
    return True

