def max_herb_value(T: int, M: int, herbs: list) -> int:
    """
    Calculate the maximum total value of herbs that can be picked within a given time limit.

    This function solves a variation of the 0/1 knapsack problem where each herb can be
    picked at most once and has an associated time cost and value.

    Args:
        T (int): The total time available for picking herbs. Must be non-negative.
        M (int): The number of different herbs in the cave. Should match len(herbs) if provided.
            Negative values are treated as zero.
        herbs (List[Tuple[int, int]]): A list of tuples, each containing two integers:
            the time required to pick the herb and its value. Both elements must be
            non-negative integers.

    Returns:
        int: The maximum total value of herbs that can be picked within the time limit.
             If inputs are invalid, 0 is returned.
    """
    try:
        # Validate basic types and values
        if not isinstance(T, int) or T < 0:
            return 0
        if not isinstance(M, int) or M < 0:
            M = 0
        if not isinstance(herbs, list):
            return 0
        if len(herbs) != M:
            # If the provided M doesn't match the actual list length, adjust M
            M = len(herbs)

        # Filter out invalid herb entries
        cleaned_herbs = []
        for item in herbs:
            if not (isinstance(item, tuple) and len(item) == 2):
                continue
            time_cost, value = item
            if not (isinstance(time_cost, int) and isinstance(value, int)):
                continue
            if time_cost < 0 or value < 0:
                continue
            cleaned_herbs.append((time_cost, value))

        # If no valid herbs or no time, return 0
        if not cleaned_herbs or T == 0:
            return 0

        # Initialize DP array
        dp = [0] * (T + 1)

        for time_cost, value in cleaned_herbs:
            if time_cost == 0:
                # Adding a zero-time herb increases value at all capacities
                # Since we can only take each herb once, we apply it once
                for cap in range(T, -1, -1):
                    if dp[cap] + value > dp[cap]:
                        dp[cap] = dp[cap] + value
                continue
            if time_cost > T:
                # Cannot pick this herb within the time limit
                continue
            # 0/1 Knapsack update, iterate backwards
            for cap in range(T, time_cost - 1, -1):
                new_val = dp[cap - time_cost] + value
                if new_val > dp[cap]:
                    dp[cap] = new_val

        return max(dp)
    except Exception:
        # Any unexpected error leads to a safe default of 0
        return 0

