def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    """
    Calculate the minimum remaining space in a box after trying to fit a number of items with given volumes.
    """
    # Input validation
    if V < 0:
        raise ValueError("Box capacity V must be non-negative.")
    if n < 0:
        raise ValueError("Number of items n must be non-negative.")
    if n > len(volumes):
        raise ValueError("Number of items n cannot exceed the length of volumes list.")
    if any(v < 0 for v in volumes[:n]):
        raise ValueError("Volume values must be non-negative.")

    # If there are no items or the box is empty, no space can be occupied.
    if V == 0 or n == 0:
        return V

    # Dynamic programming approach to the 0/1 knapsack problem.
    dp = [False] * (V + 1)
    dp[0] = True

    for vol in volumes[:n]:
        if vol > V:
            # Item cannot fit in the box, skip it.
            continue
        # Traverse backwards to avoid reusing the same item multiple times.
        for capacity in range(V, vol - 1, -1):
            if dp[capacity - vol]:
                dp[capacity] = True

    # Find the maximum capacity that can be fully utilized.
    max_occupied = max(i for i, occupied in enumerate(dp) if occupied)

    # Return the remaining space in the box.
    return V - max_occupied

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.

    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    # Validate input
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    if any(not isinstance(h, (int, float)) for h in heights):
        raise TypeError("all heights must be numeric")

    n = len(heights)
    if n <= 1:
        return 0  # already a bitonic sequence

    # Longest increasing subsequence ending at each index
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1

    # Longest decreasing subsequence starting at each index
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[i] > heights[j] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    # Find the maximum length of a bitonic subsequence
    max_bitonic = 0
    for i in range(n):
        bitonic_length = inc[i] + dec[i] - 1  # peak counted twice
        if bitonic_length > max_bitonic:
            max_bitonic = bitonic_length

    # Minimum removals to achieve a bitonic subsequence
    return n - max_bitonic

